<?php $this->assign('title', 'Checklists'); ?>
<div class="mb-7 flex flex-wrap items-center justify-between gap-4"><div><p class="mb-2 text-xs font-semibold uppercase tracking-widest text-brand-600">Manutenção preventiva</p><h1 class="page-title">Checklists</h1><p class="muted mt-2">Organize os cadastros e a programação da sua equipe.</p></div><?php if ($isAdmin): ?><a class="btn" href="<?= $this->Url->build('/checklists/novo') ?>"><?= $this->element('icon', ['name' => 'plus']) ?> Novo checklist</a><?php endif; ?></div>
<section class="panel overflow-hidden"><form method="get" class="flex flex-wrap items-end gap-3 border-b border-slate-200 p-5"><div class="min-w-48 flex-1"><label for="search">Buscar checklist</label><input id="search" type="search" name="q" value="<?= h($search) ?>" placeholder="Nome, código ou área..."></div><div><label for="status">Status</label><select id="status" name="status"><option value="">Todos os status</option><option value="ATIVO" <?= $status === 'ATIVO' ? 'selected' : '' ?>>Ativos</option><option value="PAUSADO" <?= $status === 'PAUSADO' ? 'selected' : '' ?>>Pausados</option></select></div><button class="btn-secondary" type="submit">Filtrar</button><?php if ($search || $status): ?><a class="btn-secondary" href="<?= $this->Url->build('/checklists') ?>">Limpar</a><?php endif; ?></form>
<?php if (count($checklists) === 0): ?><div class="px-6 py-16 text-center"><h2 class="text-lg font-semibold">Nenhum checklist encontrado</h2><p class="muted mt-2"><?= $search || $status ? 'Tente outra busca ou remova os filtros.' : 'Os checklists cadastrados aparecerão aqui.' ?></p></div>
<?php else: ?><div class="overflow-x-auto"><table class="w-full"><thead><tr><th>Checklist</th><th>Área / setor</th><th>Periodicidade</th><th>Data inicial</th><th>Status</th><th>Ações</th></tr></thead><tbody>
<?php foreach ($checklists as $item): ?><tr class="hover:bg-slate-50/70"><td class="min-w-52"><a class="font-semibold text-slate-800 hover:text-brand-700" href="<?= $this->Url->build(['action' => 'view', $item->id]) ?>"><?= h($item->name) ?></a><p class="mt-1 text-xs text-slate-500"><?= h($item->code) ?></p></td><td><?= h($item->area) ?><?php if ($item->route): ?><p class="mt-1 text-xs text-slate-500">Rota: <?= h($item->route) ?></p><?php endif; ?></td><td class="whitespace-nowrap"><?= h($item->current_schedule?->interval_days ?? '—') ?> dias</td><td class="whitespace-nowrap"><?= h($item->current_schedule?->start_date?->format('d/m/Y') ?? '—') ?></td><td><span class="badge <?= $item->status === 'PAUSADO' ? 'badge-paused' : '' ?>"><?= h($item->status) ?></span></td><td><div class="flex gap-4"><a class="py-2 font-semibold text-brand-700" href="<?= $this->Url->build(['action' => 'view', $item->id]) ?>">Ver</a><?php if ($isAdmin): ?><a class="py-2 text-slate-600" href="<?= $this->Url->build(['action' => 'edit', $item->id]) ?>">Editar</a><?php endif; ?></div></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
